package httpapi
import("context";"encoding/json";"net/http";"time";"github.com/go-chi/chi/v5")
func(h *Handler)roomReadOnly(w http.ResponseWriter,r *http.Request){var body map[string]bool;if err:=json.NewDecoder(r.Body).Decode(&body);err!=nil||!body["enabled"]{write(w,400,envelope{OK:false,Error:&apiError{Code:"invalid_request",Message:"enabled must be true"}});return};ctx,cancel:=context.WithTimeout(r.Context(),30*time.Second);defer cancel();roomID:=chi.URLParam(r,"roomID");if err:=h.synapse.SetRoomReadOnly(ctx,roomID);err!=nil{h.logger.Error().Err(err).Str("room_id",roomID).Msg("failed to set room read-only");write(w,502,envelope{OK:false,Error:&apiError{Code:"room_readonly_failed",Message:"Unable to update room power levels"}});return};write(w,200,envelope{OK:true,Data:map[string]any{"room_id":roomID,"read_only":true}})}
